(* ================================================================= *)
(*  BaselZeta18Poly.v  —  the Newton p₉ polynomial identity.          *)
(*  Standalone algebraic identity in one real variable x, minimal     *)
(*  imports so the degree-18 [field] stays fast.                      *)
(* ================================================================= *)

From Stdlib Require Import Reals Lra.
Open Scope R_scope.

Lemma cot18_poly_id : forall x : R,
  (x*(2*x-1)/3)^9
