    - 27*(x*(2*x-1)/3)^2*((64*x^6 - 480*x^5 + 1360*x^4 - 1800*x^3 + 1096*x^2 - 240*x) / 5040)*((256*x^8 - 3584*x^7 + 20608*x^6 - 62720*x^5 + 108304*x^4 - 105056*x^3 + 52272*x^2 - 10080*x) / 362880)
