    + 9*((262144*x^18 - 20054016*x^17 + 708575232*x^16 - 15341322240*x^15 + 227681599488*x^14 - 2454739402752*x^13 + 19878800441344*x^12 - 123295117271040*x^11 + 591795092308992*x^10 - 2205749914587648*x^9 + 6367192396271616*x^8 - 14109243671577600*x^7 + 23616809551000576*x^6 - 29097596987011584*x^5 + 25333023611639808*x^4 - 14572819556997120*x^3 + 4893622362316800*x^2 - 711374856192000*x) / 121645100408832000)
  = (57497354240*x^18 + 517476188160*x^17 + 1348049829888*x^16 - 945061625856*x^15
     - 8729222676480*x^14 - 3512869355520*x^13 + 27870040670208*x^12 + 17404258222080*x^11
